mkdir -p /Users/melihgenel/Desktop/yz50-hackathon-v2/out/final-refine && cd /Users/melihgenel/Desktop/yz50-hackathon-v2/out/final-refine && cat > gen.py <<'PYEOF'
import json
BASE = "https://yz50-bank-mock.kirgilmert.workers.dev/voice/v1/"

HELP = r'''
import json
import re
import datetime
MONTHS = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
def sv(k):
    v = vars.get(k)
    if v is None:
        return ''
    v = str(v)
    if '{' in v:
        return ''
    return v
def num(v):
    try:
        return float(v)
    except Exception:
        return 0.0
def pdate(s):
    m = re.match(r'^\s*(\d{1,2})\.(\d{1,2})\.(\d{4})', str(s))
    if not m:
        return None
    try:
        return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except Exception:
        return None
def sdate(d):
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
def today():
    m = re.match(r'^\s*(\d{4})-(\d{2})-(\d{2})', sv('now'))
    if m:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return None
def dsuf(d):
    y = d.year
    one = y % 10
    if one:
        return ['', 'dir', 'dir', 'tür', 'tür', 'tir', 'dır', 'dir', 'dir', 'dur'][one]
    ten = (y // 10) % 10
    return ['dir', 'dur', 'dir', 'dur', 'tır', 'dir', 'tır', 'tir', 'dir', 'dır'][ten]
CUR = dict(TL=('Türk Lirası', 'kuruş'), USD=('Dolar', 'sent'), EUR=('Euro', 'sent'), GBP=('İngiliz Sterlini', 'peni'))
SUF = dict(Lirası='dır', kuruş='tur', Dolar='dır', sent='tir', Euro='dur', Sterlini='dir', peni='dir')
def amt(x, c):
    cents = int(round(abs(num(x)) * 100))
    whole = cents // 100
    frac = cents % 100
    s = str(whole)
    out = ''
    while len(s) > 3:
        out = '.' + s[-3:] + out
        s = s[:-3]
    out = s + out
    t = out + ' ' + CUR[c][0]
    if frac:
        t = t + ' ' + str(frac) + ' ' + CUR[c][1]
    return t
def fin(t):
    return t + "'" + SUF.get(t.split(' ')[-1], 'dir') + '.'
def spaced(d):
    return ' '.join(list(str(d)))
def norm(s):
    s = str(s)
    for a, b in (('İ', 'i'), ('I', 'ı'), ('Ş', 'ş'), ('Ğ', 'ğ'), ('Ü', 'ü'), ('Ö', 'ö'), ('Ç', 'ç')):
        s = s.replace(a, b)
    s = s.lower()
    s = re.sub(r'[^a-z0-9ığüşöç ]', ' ', s)
    return ' '.join(s.split())
def cards():
    pre = 'list_cards_response.data.data.cards.'
    idx = set()
    for k in list(vars.keys()):
        if str(k).startswith(pre):
            p = str(k)[len(pre):].split('.')
            if p[0].isdigit():
                idx.add(int(p[0]))
    out = []
    for i in sorted(idx):
        b = pre + str(i) + '.'
        cn = sv(b + 'cardNumber')
        if not cn:
            continue
        name = sv(b + 'productName').strip()
        if len(name) > 30:
            name = ''
        l4 = sv(b + 'cardNumberLast4') or cn[-4:]
        out.append(dict(n=cn, l4=l4, name=name, main=(sv(b + 'isMainCard').lower() != 'false')))
    return out
def cname(c):
    if c['name']:
        return c['name']
    return 'sonu ' + spaced(c['l4']) + ' ile biten kart'
def sel_question(cs):
    ex = []
    for c in cs:
        if c['main'] and c['name'] and c['name'] not in ex:
            ex.append(c['name'])
    if len(ex) >= 2:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
    if len(ex) == 1:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + ex[0] + ' diyebilirsiniz ya da kartınızın son dört hanesini söyleyebilirsiniz.'
    return 'Hangi kartınızın borcunu öğrenmek istersiniz? Kartınızın son dört hanesini söyleyebilirsiniz.'
def all_names(cs):
    ex = []
    for c in cs:
        if c['main'] and cname(c) not in ex:
            ex.append(cname(c))
    return ', '.join(ex)
'''

def wrap(body):
    code = HELP + "\ntry:\n" + "\n".join("    " + l for l in body.strip("\n").split("\n")) + "\nexcept Exception as _e:\n    vars['runtime_error'] = str(_e)[:300]\n"
    chk = code.replace("{{card_name}}", "").replace("{{digits}}", "").replace("{{week}}", "")
    assert "{{" not in chk and "}}" not in chk, "double braces"
    return code

PREP_CARDS = r'''
st = sv('cl_status')
cs = cards()
vars['sel_tries'] = '0'
vars['sel_pending'] = ''
vars['sel_flag'] = ''
if st == '404':
    vars['cl_flag'] = 'none'
elif st != '200' or not cs:
    vars['cl_flag'] = 'error'
else:
    mains = [c for c in cs if c['main']]
    vars['card_count'] = str(len(mains))
    vars['card_names'] = all_names(cs)
    if len(cs) == 1 and mains:
        vars['sel_card'] = cs[0]['n']
        vars['sel_l4'] = cs[0]['l4']
        vars['sel_name'] = cs[0]['name']
        vars['cl_flag'] = 'one'
    elif not mains:
        vars['cl_flag'] = 'none'
    else:
        vars['select_prompt'] = sel_question(cs)
        vars['cl_flag'] = 'multi'
'''

CHOOSE = r'''
a_name = r"""{{card_name}}~"""[:-1]
a_dig = r"""{{digits}}~"""[:-1]
if '{' in a_name:
    a_name = ''
if '{' in a_dig:
    a_dig = ''
cs = cards()
q = sel_question(cs)
dig = re.sub(r'\D', '', a_dig)
nm = norm(a_name)
for w in ('kartım', 'kartımın', 'kartı', 'kart', 'olan', 'isimli'):
    nm = ' '.join([t for t in nm.split() if t != w])
tries = int(num(sv('sel_tries')))
pend = sv('sel_pending')
cand = []
say = ''
def by_name(n):
    ex = [c for c in cs if norm(c['name']) == n and c['name']]
    if ex:
        return ex
    toks = n.split()
    r = [c for c in cs if c['name'] and all(t in norm(c['name']).split() for t in toks)]
    if r:
        return r
    toks2 = [t for t in toks if t != 'yıldız']
    if toks2:
        return [c for c in cs if c['name'] and all(t in norm(c['name']) for t in toks2)]
    return []
if len(dig) >= 4:
    pool = cs
    if pend:
        pp = [c for c in cs if norm(c['name']) == pend]
        if pp:
            pool = pp
    cand = [c for c in pool if c['l4'] == dig[-4:]]
    if not cand and pool is not cs:
        cand = [c for c in cs if c['l4'] == dig[-4:]]
    if len(cand) > 1 and len(dig) >= 6:
        full = [c for c in cand if '*' not in c['n']]
        if full and len(full) == len(cand):
            f2 = [c for c in cand if c['n'].endswith(dig) or c['n'] == dig]
            if f2:
                cand = f2
        elif len(dig) >= 16:
            f2 = [c for c in cand if c['n'][:6] == dig[:6]]
            if f2:
                cand = f2
    if len(cand) > 1:
        if len(dig) < 6:
