def eq(var, val, target, desc=None):
    return {"target_node": target, "description": desc or (var + " is " + val), "condition": {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}}
def always(target):
    return {"target_node": target, "description": "always", "condition": {"operator": "always"}}
def intent(target, desc):
    return {"target_node": target, "description": desc, "condition": {"operator": "matches_intent", "description": desc}}
def code_action(body):
    return {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": wrap(body)}}}}}
def code_node(name, body, transitions, default, tts=None):
    return {"name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": default,
            "on_enter": {"type": "tts", "text": tts} if tts else {"type": "silent"}, "pre_actions": [code_action(body)], "transitions": transitions}
def api_action(name, path, body_props, desc, retries=0):
    return {"type": "function", "config": {"timeoutMs": 30000, "maxRetries": retries}, "function": {"name": name, "handler": "__function__:api_call", "description": desc,
            "parameters": {"type": "object", "properties": {"url": {"type": "string", "default": BASE + path}, "method": {"type": "string", "default": "POST"},
            "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}, "Accept": {"type": "string", "default": "application/json"}}},
            "body": {"type": "object", "properties": {"data": {"type": "object", "properties": body_props}, "call": {"type": "object", "properties": {"lang": {"type": "string", "default": "tr"}}}}}}}}}
def api_node(name, action, status_var, nxt, tts=None):
    return {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": nxt,
            "on_enter": {"type": "tts", "text": tts} if tts else {"type": "silent"}, "on_enter_first_entry_only": False,
            "pre_actions": [action], "response_mapping": [{"path": "status_code", "variable": status_var}], "transitions": [always(nxt)]}
def end_node(name, fn, msg):
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "transitions": [],
            "terminal": {"type": "function", "function": {"name": fn, "handler": "__function__:end_call", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "custom"}, "spoken_message": {"type": "string", "default": msg}}}}}}
def code_tool(name, desc, body, args):
    props = {"code": {"type": "string", "default": wrap(body)}, "timeout_ms": {"type": "number", "default": 30000}}
    props.update(args)
    return {"type": "function", "config": {"timeoutMs": 35000}, "function": {"name": name, "handler": "__function__:code_exec", "description": desc, "parameters": {"type": "object", "properties": props, "required": list(args.keys())}}}

