      intent("end_menu", "The caller wants nothing else: says thanks, no, that is all, goodbye (teşekkürler, hayır, yok, bu kadar, iyi günler).")])
N["email_gate"] = code_node("email_gate", EMAIL_GATE, [eq("eg_flag", "yes", "email_confirm"), always("offer")], "offer")
