N["week_bounce"] = code_node("week_bounce", "vars['sw_flag'] = ''", [always("week_choose")], "week_choose")
wk_body = {"cardNumber": {"type": "string", "default": "{{sel_card}}"}, "newStatementWeek": {"type": "string", "default": "{{new_week}}"}, "statementDay": {"type": "string", "default": "{{cur_day}}"}}
N["week_decide"] = api_node("week_decide", api_action("preview_statement_week", "statement.week.decide", wk_body, "Previews the dates for the chosen week. Changes nothing.", 1), "dec_status", "week_preview")
